       1, 'Diciembre 2025', '2025-12-01', 'completado', 'pendiente', 'transferencia'
FROM Sede se JOIN Empresa e ON se.id_empresa = e.id_empresa
WHERE e.ruc = '20610423257'
AND NOT EXISTS (SELECT 1 FROM Servicio s2 JOIN Sede se2 ON s2.id_sede=se2.id_sede JOIN Empresa e2 ON se2.id_empresa=e2.id_empresa WHERE e2.ruc = '20610423257' AND s2.fecha_ejecucion = '2025-12-01')
LIMIT 1;

