SET s.estado_pago = 'pendiente', s.forma_pago = 'transferencia',
    s.id_ruta = (SELECT id_ruta FROM Ruta WHERE codigo_ruta = 'R-20251201-KYC' LIMIT 1),
    s.mes_servicio = 'Diciembre 2025'
WHERE e.ruc = '20610423257' AND s.fecha_ejecucion = '2025-12-01';


