       (SELECT id_ruta FROM Ruta WHERE codigo_ruta = 'R-20251217-DONFENG-1' LIMIT 1),
       1, 'Diciembre 2025', '2025-12-17', 'completado', 'pagado', 'yape'
FROM Sede se JOIN Empresa e ON se.id_empresa = e.id_empresa
WHERE e.ruc = '20556644471'
AND NOT EXISTS (SELECT 1 FROM Servicio s2 JOIN Sede se2 ON s2.id_sede=se2.id_sede JOIN Empresa e2 ON se2.id_empresa=e2.id_empresa WHERE e2.ruc = '20556644471' AND s2.fecha_ejecucion = '2025-12-17')
LIMIT 1;

UPDATE Servicio s JOIN Sede se ON s.id_sede=se.id_sede JOIN Empresa e ON se.id_empresa=e.id_empresa
SET s.estado_pago = 'pagado', s.forma_pago = 'yape',
    s.id_ruta = (SELECT id_ruta FROM Ruta WHERE codigo_ruta = 'R-20251217-DONFENG-1' LIMIT 1),
    s.mes_servicio = 'Diciembre 2025'
WHERE e.ruc = '20556644471' AND s.fecha_ejecucion = '2025-12-17';


